cr=good(admin,'/finance/expenses/'+claim['id']+'/submit','POST',{})['request'];actual=good(admin,p+'/budgets/'+budget['id']+'/actual');check('submitted is commitment',actual['committed']==50 and actual['actual']==0);approve(cr);actual=good(admin,p+'/budgets/'+budget['id']+'/actual');check('approval consumes commitment once',actual['committed']==0 and actual['actual']==50 and actual['available']==450)
good(review,'/finance/expenses/'+claim['id']+'/reimburse','POST',{'amount':'20','reference':'REIMB-'+tag,'date':date});check('partial reimbursement separate',next(x for x in good(admin,p+'/expenses') if x['id']==claim['id'])['paid']==20);check('budget not double counted',good(admin,p+'/budgets/'+budget['id']+'/actual')['available']==450)
